// Attempt to restore a snapshot if there are any.
if err := r.restoreSnapshot(); err != nil {
	return nil, err
}

if err := r.restoreFromCommittedLogs(); err != nil {
	return nil, err
}

// Scan through the log for any configuration change entries.
snapshotIndex, _ := r.getLastSnapshot()
lastappliedIndex := r.getLastApplied()
for index := max(snapshotIndex, lastappliedIndex) + 1; index <= lastLog.Index; index++ {
	var entry Log
	if err := r.logs.GetLog(index, &entry); err != nil {
		r.logger.Error("failed to get log", "index", index, "error", err)
		panic(err)
	}
	if err := r.processConfigurationLogEntry(&entry); err != nil {
		return nil, err
	}
}

// restoreFromCommittedLogs recovers the Raft node from committed logs.
func (r *Raft) restoreFromCommittedLogs() error {
	if !r.RestoreCommittedLogs {
		return nil
	}

	// If the store implements CommitTrackingLogStore, we can read the commit index from the store.
	// This is useful when the store is able to track the commit index and we can avoid replaying logs.
	store, ok := r.logs.(CommitTrackingLogStore)
	if !ok {
		r.logger.Warn("restore committed logs enabled but log store does not support it", "log_store", fmt.Sprintf("%T", r.logs))
		return ErrIncompatibleLogStore
	}

	commitIndex, err := store.GetCommitIndex()
	if err != nil {
		r.logger.Error("failed to get commit index from store", "error", err)
		return err
	}

	lastIndex, err := r.logs.LastIndex()
	if err != nil {
		r.logger.Error("failed to get last log index from store", "error", err)
		return err
	}
	if commitIndex > lastIndex {
		commitIndex = lastIndex
	}

	r.setCommitIndex(commitIndex)
	r.processLogs(commitIndex, nil)
	return nil
}

// NewRaft is used to construct a new Raft node. It takes a configuration, as well
// as implementations of various interfaces that are required. If we have any
// old state, such as snapshots, logs, peers, etc, all those will be restored
// when creating the Raft node.

func (r *Raft) restoreSnapshot() error {
	snapshots, err := r.snapshots.List()
	if err != nil {
		r.logger.Error("failed to list snapshots", "error", err)
		return err
	}

	// Try to load in order of newest to oldest
	for _, snapshot := range snapshots {
		if success := r.tryRestoreSingleSnapshot(snapshot); !success {
			continue
		}

		// Update the lastApplied so we don't replay old logs
		r.setLastApplied(snapshot.Index)

		// Update the last stable snapshot info
		r.setLastSnapshot(snapshot.Index, snapshot.Term)

		// Update the configuration
		var conf Configuration
		var index uint64
		if snapshot.Version > 0 {
			conf = snapshot.Configuration
			index = snapshot.ConfigurationIndex
		} else {
			var err error
			if conf, err = decodePeers(snapshot.Peers, r.trans); err != nil {
				return err
			}
			index = snapshot.Index
		}
		r.setCommittedConfiguration(conf, index)
		r.setLatestConfiguration(conf, index)

		// Success!
		return nil
	}

	// If we had snapshots and failed to load them, its an error
	if len(snapshots) > 0 {
		return fmt.Errorf("failed to load any existing snapshots")
	}
	return nil
}

// processConfigurationLogEntry takes a log entry and updates the latest
// configuration if the entry results in a new configuration. This must only be
// called from the main thread, or from NewRaft() before any threads have begun.
func (r *Raft) processConfigurationLogEntry(entry *Log) error {
	switch entry.Type {
	case LogConfiguration:
		r.setCommittedConfiguration(r.configurations.latest, r.configurations.latestIndex)
		r.setLatestConfiguration(DecodeConfiguration(entry.Data), entry.Index)

	case LogAddPeerDeprecated, LogRemovePeerDeprecated:
		r.setCommittedConfiguration(r.configurations.latest, r.configurations.latestIndex)
		conf, err := decodePeers(entry.Data, r.trans)
		if err != nil {
			return err
		}
		r.setLatestConfiguration(conf, entry.Index)
	}
	return nil
}

if r.configurations.latestIndex == 0 {
	if !didWarn {
		r.logger.Warn("no known peers, aborting election")
		didWarn = true
	}
} else if r.configurations.latestIndex == r.configurations.committedIndex &&
	!hasVote(r.configurations.latest, r.localID) {
	if !didWarn {
		r.logger.Warn("not part of stable configuration, aborting election")
		didWarn = true
	}
} else {
	metrics.IncrCounter([]string{"raft", "transition", "heartbeat_timeout"}, 1)
	if hasVote(r.configurations.latest, r.localID) {
		r.logger.Warn("heartbeat timeout reached, starting election", "last-leader-addr", lastLeaderAddr, "last-leader-id", lastLeaderID)
		r.setState(Candidate)
		return
	} else if !didWarn {
		r.logger.Warn("heartbeat timeout reached, not part of a stable configuration or a non-voter, not triggering a leader election")
		didWarn = true
	}
}

if len(req.ID) > 0 {
	candidateID := ServerID(req.ID)
	// if the Servers list is empty that mean the cluster is very likely trying to bootstrap,
	// Grant the vote
	if len(r.configurations.latest.Servers) > 0 && !inConfiguration(r.configurations.latest, candidateID) {
		r.logger.Warn("rejecting vote request since node is not in configuration",
			"from", candidate)
		return
	}
}

if len(r.configurations.latest.Servers) > 0 && !inConfiguration(r.configurations.latest, candidateID) {
	r.logger.Warn("rejecting pre-vote request since node is not in configuration",
		"from", candidate)
	return
}

// RestoreCommittedLogs controls if the Raft server should use the restore committed logs
// mechanism. Restore committed logs requires a LogStore implementation that
// support commit tracking. When such a store is used and this config
// enabled, raft nodes will replay all known-committed logs on disk
// before completing `NewRaft` on startup. This is mainly useful where
// the application allows relaxed-consistency reads from followers as it
// will reduce how far behind the follower's FSM is when it starts. If all reads
// are forwarded to the leader then there won't be observable benefit from this feature.
//
// Notice: If this is enabled, the log store MUST implement the CommitTrackingLogStore
// interface. Otherwise, Raft will fail to start and return ErrIncompatibleLogStore.
RestoreCommittedLogs bool

func TestRaft_RestoreCommittedLogs(t *testing.T) {
	// Make the cluster
	conf := inmemConfig(t)
	conf.TrailingLogs = 10
	conf.RestoreCommittedLogs = true
	opts := &MakeClusterOpts{
		Peers:              1,
		Bootstrap:          true,
		Conf:               conf,
		CommitTrackingLogs: true,
	}
	c := MakeClusterCustom(t, opts)
	defer c.Close()

	leader := c.Leader()

	// Commit a lot of things
	var future Future
	for i := 0; i < 100; i++ {
		future = leader.Apply([]byte(fmt.Sprintf("test%d", i)), 0)
	}

	// Wait for the last future to apply
	if err := future.Error(); err != nil {
		t.Fatalf("err: %v", err)
	}

	// Take a snapshot
	snapFuture := leader.Snapshot()
	if err := snapFuture.Error(); err != nil {
		t.Fatalf("err: %v", err)
	}

	// Check for snapshot
	snaps, _ := leader.snapshots.List()
	if len(snaps) != 1 {
		t.Fatalf("should have a snapshot")
	}
	snap := snaps[0]

	// Logs should be trimmed
	firstIdx, err := leader.logs.FirstIndex()
	if err != nil {
		t.Fatalf("err: %v", err)
	}

	if firstIdx != snap.Index-conf.TrailingLogs+1 {
		t.Fatalf("should trim logs to %d: but is %d", snap.Index-conf.TrailingLogs+1, firstIdx)
	}

	// Commit a lot of things (for restore committed logs test)
	for i := 0; i < 100; i++ {
		future = leader.Apply([]byte(fmt.Sprintf("test%d", i)), 0)
	}

	// Wait for the last future to apply
	if err := future.Error(); err != nil {
		t.Fatalf("err: %v", err)
	}

	// Shutdown
	shutdown := leader.Shutdown()
	if err := shutdown.Error(); err != nil {
		t.Fatalf("err: %v", err)
	}

	// Restart the Raft
	r := leader
	// Can't just reuse the old transport as it will be closed
	_, trans2 := NewInmemTransport(r.trans.LocalAddr())
	cfg := r.config()
	r, err = NewRaft(&cfg, r.fsm, r.logs, r.stable, r.snapshots, trans2)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	c.rafts[0] = r

	store, ok := r.logs.(CommitTrackingLogStore)
	if !ok {
		t.Fatal("err: raft log store does not implement CommitTrackingLogStore interface")
	}
	commitIdx, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	// We should have applied all committed logs
	if last := r.getLastApplied(); last != commitIdx {
		t.Fatalf("bad last index: %d, expecting %d", last, commitIdx)
	}

	// Expect: snap.Index --- commitIdx --- lastIdx
	lastIdx, err := r.logs.LastIndex()
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	assert.LessOrEqual(t, snap.Index, commitIdx)
	assert.LessOrEqual(t, commitIdx, lastIdx)
}

func (r *Raft) appendConfigurationEntry(future *configurationChangeFuture) {
	configuration, err := nextConfiguration(r.configurations.latest, r.configurations.latestIndex, future.req)
	if err != nil {
		future.respond(err)
		return
	}

	r.logger.Info("updating configuration",
		"command", future.req.command,
		"server-id", future.req.serverID,
		"server-addr", future.req.serverAddress,
		"servers", hclog.Fmt("%+v", configuration.Servers))

	// In pre-ID compatibility mode we translate all configuration changes
	// in to an old remove peer message, which can handle all supported
	// cases for peer changes in the pre-ID world (adding and removing
	// voters). Both add peer and remove peer log entries are handled
	// similarly on old Raft servers, but remove peer does extra checks to
	// see if a leader needs to step down. Since they both assert the full
	// configuration, then we can safely call remove peer for everything.
	if r.protocolVersion < 2 {
		future.log = Log{
			Type: LogRemovePeerDeprecated,
			Data: encodePeers(configuration, r.trans),
		}
	} else {
		future.log = Log{
			Type: LogConfiguration,
			Data: EncodeConfiguration(configuration),
		}
	}

	r.dispatchLogs([]*logFuture{&future.logFuture})
	index := future.Index()
	r.setLatestConfiguration(configuration, index)
	r.leaderState.commitment.setConfiguration(configuration)
	r.startStopReplication()
}

func (r *Raft) configurationChangeChIfStable() chan *configurationChangeFuture {
	// Have to wait until:
	// 1. The latest configuration is committed, and
	// 2. This leader has committed some entry (the noop) in this term
	//    https://groups.google.com/forum/#!msg/raft-dev/t4xj6dJTP6E/d2D9LrWRza8J
	if r.configurations.latestIndex == r.configurations.committedIndex &&
		r.getCommitIndex() >= r.leaderState.commitment.startIndex {
		return r.configurationChangeCh
	}
	return nil
}

func nextConfiguration(current Configuration, currentIndex uint64, change configurationChangeRequest) (Configuration, error) {
	if change.prevIndex > 0 && change.prevIndex != currentIndex {
		return Configuration{}, fmt.Errorf("configuration changed since %v (latest is %v)", change.prevIndex, currentIndex)
	}

	configuration := current.Clone()
	switch change.command {
	case AddVoter:
		newServer := Server{
			Suffrage: Voter,
			ID:       change.serverID,
			Address:  change.serverAddress,
		}
		found := false
		for i, server := range configuration.Servers {
			if server.ID == change.serverID {
				if server.Suffrage == Voter {
					configuration.Servers[i].Address = change.serverAddress
				} else {
					configuration.Servers[i] = newServer
				}
				found = true
				break
			}
		}
		if !found {
			configuration.Servers = append(configuration.Servers, newServer)
		}
	case AddNonvoter:
		newServer := Server{
			Suffrage: Nonvoter,
			ID:       change.serverID,
			Address:  change.serverAddress,
		}
		found := false
		for i, server := range configuration.Servers {
			if server.ID == change.serverID {
				if server.Suffrage != Nonvoter {
					configuration.Servers[i].Address = change.serverAddress
				} else {
					configuration.Servers[i] = newServer
				}
				found = true
				break
			}
		}
		if !found {
			configuration.Servers = append(configuration.Servers, newServer)
		}
	case DemoteVoter:
		for i, server := range configuration.Servers {
			if server.ID == change.serverID {
				configuration.Servers[i].Suffrage = Nonvoter
				break
			}
		}
	case RemoveServer:
		for i, server := range configuration.Servers {
			if server.ID == change.serverID {
				configuration.Servers = append(configuration.Servers[:i], configuration.Servers[i+1:]...)
				break
			}
		}
	case Promote:
		for i, server := range configuration.Servers {
			if server.ID == change.serverID && server.Suffrage == Staging {
				configuration.Servers[i].Suffrage = Voter
				break
			}
		}
	}

	// Make sure we didn't do something bad like remove the last voter
	if err := checkConfiguration(configuration); err != nil {
		return Configuration{}, err
	}

	return configuration, nil
}

harness.source:
package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

// caEvent prints one observation as a single JSON line for controller parsing.
func caEvent(t *testing.T, kind string, fields map[string]interface{}) {
	fields["event"] = kind
	b, err := json.Marshal(fields)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

func waitLeaderState(r *Raft, d time.Duration) bool {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// TestAssurance_RestartConfigFromCommittedLogs restarts a single-voter node
// whose configuration entry lives in the log (never snapshotted) and observes
// whether the node still knows the bootstrapped configuration, with
// RestoreCommittedLogs on and off, and with a covering snapshot as a control.
func TestAssurance_RestartConfigFromCommittedLogs(t *testing.T) {
	cases := []struct {
		mode         string
		restore      bool
		takeSnapshot bool
	}{
		{mode: "restore_on_no_snapshot", restore: true, takeSnapshot: false},
		{mode: "restore_off_no_snapshot", restore: false, takeSnapshot: false},
		{mode: "restore_on_with_snapshot", restore: true, takeSnapshot: true},
	}

	for _, tc := range cases {
		runRestartCase(t, tc.mode, tc.restore, tc.takeSnapshot)
	}
}

func runRestartCase(t *testing.T, mode string, restore, takeSnapshot bool) {
	conf := inmemConfig(t)
	conf.RestoreCommittedLogs = restore
	conf.SnapshotThreshold = 1 << 40
	conf.SnapshotInterval = 10 * time.Minute
	conf.TrailingLogs = 10

	addr, trans := NewInmemTransport(ServerAddress("A"))
	conf.LocalID = ServerID(addr)
	logs := NewInmemCommitTrackingStore()
	stable := NewInmemStore()
	snaps := NewInmemSnapshotStore()

	configuration := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: ServerID(addr), Address: addr},
	}}
	if err := BootstrapCluster(conf, logs, stable, snaps, trans, configuration); err != nil {
		t.Fatalf("[%s] bootstrap: %v", mode, err)
	}

	r, err := NewRaft(conf, new(MockFSM), logs, stable, snaps, trans)
	if err != nil {
		t.Fatalf("[%s] first NewRaft: %v", mode, err)
	}
	firstLeader := waitLeaderState(r, 5*time.Second)

	for i := 0; i < 5; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("cmd%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("[%s] apply %d: %v", mode, i, err)
		}
	}

	if takeSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("[%s] snapshot: %v", mode, err)
		}
	}

	before := r.GetConfiguration()
	if err := before.Error(); err != nil {
		t.Fatalf("[%s] GetConfiguration before restart: %v", mode, err)
	}
	snapList, err := snaps.List()
	if err != nil {
		t.Fatalf("[%s] list snapshots: %v", mode, err)
	}
	stagedCommit, err := logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("[%s] GetCommitIndex: %v", mode, err)
	}
	lastIdx, err := logs.LastIndex()
	if err != nil {
		t.Fatalf("[%s] LastIndex: %v", mode, err)
	}

	caEvent(t, "pre_restart", map[string]interface{}{
		"mode":              mode,
		"restore_committed": restore,
		"took_snapshot":     takeSnapshot,
		"became_leader":     firstLeader,
		"servers_before":    len(before.Configuration().Servers),
		"snapshot_count":    len(snapList),
		"staged_commit_idx": stagedCommit,
		"log_last_index":    lastIdx,
		"last_applied":      r.AppliedIndex(),
		"commit_index":      r.CommitIndex(),
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("[%s] shutdown: %v", mode, err)
	}

	// Restart on the same durable stores with a fresh transport.
	_, trans2 := NewInmemTransport(addr)
	r2, err := NewRaft(conf, new(MockFSM), logs, stable, snaps, trans2)
	if err != nil {
		t.Fatalf("[%s] second NewRaft: %v", mode, err)
	}
	after := r2.GetConfiguration()
	if err := after.Error(); err != nil {
		t.Fatalf("[%s] GetConfiguration after restart: %v", mode, err)
	}
	// Give the node a fair opportunity to campaign again.
	leaderAgain := waitLeaderState(r2, 3*time.Second)

	caEvent(t, "post_restart", map[string]interface{}{
		"mode":           mode,
		"servers_after":  len(after.Configuration().Servers),
		"config_preserved": len(after.Configuration().Servers) == len(before.Configuration().Servers),
		"became_leader":  leaderAgain,
		"last_applied":   r2.AppliedIndex(),
		"commit_index":   r2.CommitIndex(),
		"snapshot_count": len(snapList),
		"log_last_index": lastIdx,
		"staged_commit":  stagedCommit,
	})

	_ = r2.Shutdown().Error()
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func gapEvent(t *testing.T, kind string, fields map[string]interface{}) {
	fields["event"] = kind
	b, err := json.Marshal(fields)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

func serversOf(r *Raft) map[string]bool {
	out := map[string]bool{}
	f := r.GetConfiguration()
	if err := f.Error(); err != nil {
		return out
	}
	for _, s := range f.Configuration().Servers {
		out[string(s.ID)] = true
	}
	return out
}

func newestConfigEntryIdx(logs LogStore) uint64 {
	first, err := logs.FirstIndex()
	if err != nil {
		return 0
	}
	last, err := logs.LastIndex()
	if err != nil {
		return 0
	}
	for i := last; i >= first && i > 0; i-- {
		var l Log
		if logs.GetLog(i, &l) == nil && l.Type == LogConfiguration {
			return i
		}
	}
	return 0
}

func waitAnyLeader(rs []*Raft, d time.Duration) *Raft {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		for _, r := range rs {
			if r.State() == Leader {
				return r
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	return nil
}

// TestAssurance_StaleConfigurationAfterRestart creates a two-voter cluster,
// snapshots it, then commits a configuration change that adds a third voter
// (which never runs, since two acks are a quorum of three). It then restarts the
// leader and observes whether the restarted node still knows the newest
// committed configuration, and what configuration it bases a later change on.
func TestAssurance_StaleConfigurationAfterRestart(t *testing.T) {
	for _, mode := range []string{"restore_on", "restore_off"} {
		runStaleConfigCase(t, mode, mode == "restore_on")
	}
}

func runStaleConfigCase(t *testing.T, mode string, restore bool) {
	conf := inmemConfig(t)
	conf.RestoreCommittedLogs = restore
	conf.SnapshotThreshold = 1 << 40
	conf.SnapshotInterval = 10 * time.Minute
	conf.TrailingLogs = 10

	addrA, transA := NewInmemTransport(ServerAddress("A"))
	confA := *conf
	confA.LocalID = ServerID(addrA)
	logsA := NewInmemCommitTrackingStore()
	stableA := NewInmemStore()
	snapsA := NewInmemSnapshotStore()

	if err := BootstrapCluster(&confA, logsA, stableA, snapsA, transA, Configuration{Servers: []Server{
		{Suffrage: Voter, ID: ServerID(addrA), Address: addrA},
		{Suffrage: Voter, ID: ServerID("B"), Address: ServerAddress("B")},
	}}); err != nil {
		t.Fatalf("[%s] bootstrap: %v", mode, err)
	}

	rA, err := NewRaft(&confA, new(MockFSM), logsA, stableA, snapsA, transA)
	if err != nil {
		t.Fatalf("[%s] NewRaft A: %v", mode, err)
	}

	addrB, transB := NewInmemTransport(ServerAddress("B"))
	transA.Connect(ServerAddress("B"), transB)
	transB.Connect(ServerAddress("A"), transA)
	confB := *conf
	confB.LocalID = ServerID(addrB)
	logsB := NewInmemCommitTrackingStore()
	stableB := NewInmemStore()
	snapsB := NewInmemSnapshotStore()
	rB, err := NewRaft(&confB, new(MockFSM), logsB, stableB, snapsB, transB)
	if err != nil {
		t.Fatalf("[%s] NewRaft B: %v", mode, err)
	}

	leader := waitAnyLeader([]*Raft{rA, rB}, 8*time.Second)
	if leader == nil {
		t.Fatalf("[%s] no leader elected", mode)
	}
	leaderIsA := leader == rA

	for i := 0; i < 5; i++ {
		if err := leader.Apply([]byte(fmt.Sprintf("cmd%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("[%s] apply %d: %v", mode, i, err)
		}
	}
	if err := leader.Snapshot().Error(); err != nil {
		t.Fatalf("[%s] snapshot: %v", mode, err)
	}
	snapListA, err := snapsA.List()
	if err != nil {
		t.Fatalf("[%s] list snapshots A: %v", mode, err)
	}

	// Add a third voter that never runs; two acks (A and B) are a quorum of three.
	if err := rA.AddVoter(ServerID("C"), ServerAddress("C"), 0, 5*time.Second).Error(); err != nil {
		t.Fatalf("[%s] AddVoter C: %v", mode, err)
	}
	// Commit further entries so the configuration change is no longer the
	// newest log entry: this is what puts it inside the persisted commit index.
	for i := 0; i < 4; i++ {
		if err := rA.Apply([]byte(fmt.Sprintf("after%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("[%s] apply after %d: %v", mode, i, err)
		}
	}

	before := serversOf(rA)
	staged, err := logsA.GetCommitIndex()
	if err != nil {
		t.Fatalf("[%s] GetCommitIndex A: %v", mode, err)
	}
	lastIdx, _ := logsA.LastIndex()

	gapEvent(t, "pre_restart", map[string]interface{}{
		"mode":              mode,
		"leader_is_A":       leaderIsA,
		"servers_before":    len(before),
		"contains_c_before": before["C"],
		"snapshot_count_A":  len(snapListA),
		"log_last_index":    lastIdx,
		"staged_commit_idx": staged,
		"newest_config_idx": newestConfigEntryIdx(logsA),
	})

	if err := rA.Shutdown().Error(); err != nil {
		t.Fatalf("[%s] shutdown A: %v", mode, err)
	}

	// Restart A on the same durable stores with a fresh transport.
	_, transA2 := NewInmemTransport(addrA)
	transA2.Connect(ServerAddress("B"), transB)
	rA2, err := NewRaft(&confA, new(MockFSM), logsA, stableA, snapsA, transA2)
	if err != nil {
		t.Fatalf("[%s] second NewRaft A: %v", mode, err)
	}
	after := serversOf(rA2)
	viewB := serversOf(rB)

	gapEvent(t, "post_restart", map[string]interface{}{
		"mode":              mode,
		"servers_after":     len(after),
		"contains_c_after":  after["C"],
		"servers_view_B":    len(viewB),
		"last_applied_A":    rA2.AppliedIndex(),
		"commit_index_A":    rA2.CommitIndex(),
		"log_last_index":    lastIdx,
		"staged_commit":     staged,
		"snapshot_count_A":  len(snapListA),
		"newest_config_idx": newestConfigEntryIdx(logsA),
	})

	// Optional continuation: if the restarted node can lead again, base a
	// configuration change on whatever configuration it believes it has.
	leader2 := waitAnyLeader([]*Raft{rA2, rB}, 8*time.Second)
	stableLeader := false
	deadline := time.Now().Add(8 * time.Second)
	for time.Now().Before(deadline) && leader2 == rA2 {
		if rA2.State() == Leader {
			time.Sleep(300 * time.Millisecond)
			if rA2.State() == Leader {
				stableLeader = true
				break
			}
		}
		time.Sleep(20 * time.Millisecond)
	}
	gapEvent(t, "post_restart_leader", map[string]interface{}{
		"mode":            mode,
		"leader_is_A":     leader2 == rA2,
		"stable_A_leader": stableLeader,
	})
	if stableLeader {
		err := rA2.AddVoter(ServerID("E"), ServerAddress("E"), 0, 5*time.Second).Error()
		afterChange := serversOf(rA2)
		if err == nil {
			// Give B a moment to observe the entry as well.
			deadline := time.Now().Add(2 * time.Second)
			for time.Now().Before(deadline) {
				if serversOf(rB)["E"] {
					break
				}
				time.Sleep(10 * time.Millisecond)
			}
		}
		gapEvent(t, "after_config_change", map[string]interface{}{
			"mode":                 mode,
			"change_err":           fmt.Sprintf("%v", err),
			"servers_after_change": len(afterChange),
			"contains_c_final":     afterChange["C"],
			"contains_e_final":     afterChange["E"],
			"view_B_contains_c":    serversOf(rB)["C"],
			"view_B_contains_e":    serversOf(rB)["E"],
		})
	} else {
		gapEvent(t, "after_config_change", map[string]interface{}{
			"mode":       mode,
			"skipped":    true,
			"leader_is_A": leader2 == rA2,
		})
	}

	_ = rA2.Shutdown().Error()
	_ = rB.Shutdown().Error()
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func controlEvent(t *testing.T, kind string, fields map[string]interface{}) {
	fields["event"] = kind
	b, err := json.Marshal(fields)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

func controlWaitLeader(r *Raft, d time.Duration) bool {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// TestAssurance_ControlRestartWithoutCommittedReplay is the isolated control for
// the committed-log-replay finding: the same bootstrap, commits, restart and
// missing snapshot, but with RestoreCommittedLogs left at its default false, so
// the configuration scan is not bounded by a replayed commit index.
func TestAssurance_ControlRestartWithoutCommittedReplay(t *testing.T) {
	conf := inmemConfig(t)
	conf.RestoreCommittedLogs = false
	conf.SnapshotThreshold = 1 << 40
	conf.SnapshotInterval = 10 * time.Minute
	conf.TrailingLogs = 10

	addr, trans := NewInmemTransport(ServerAddress("A"))
	conf.LocalID = ServerID(addr)
	logs := NewInmemCommitTrackingStore()
	stable := NewInmemStore()
	snaps := NewInmemSnapshotStore()

	if err := BootstrapCluster(conf, logs, stable, snaps, trans, Configuration{Servers: []Server{
		{Suffrage: Voter, ID: ServerID(addr), Address: addr},
	}}); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}

	r, err := NewRaft(conf, new(MockFSM), logs, stable, snaps, trans)
	if err != nil {
		t.Fatalf("first NewRaft: %v", err)
	}
	if !controlWaitLeader(r, 5*time.Second) {
		t.Fatalf("node did not become leader")
	}
	for i := 0; i < 5; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("cmd%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("apply %d: %v", i, err)
		}
	}

	f := r.GetConfiguration()
	if err := f.Error(); err != nil {
		t.Fatalf("GetConfiguration before restart: %v", err)
	}
	before := len(f.Configuration().Servers)
	snapList, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	staged, err := logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex: %v", err)
	}

	controlEvent(t, "control_start", map[string]interface{}{
		"restore_committed": false,
		"servers_before":    before,
		"snapshot_count":    len(snapList),
		"staged_commit_idx": staged,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}

	_, trans2 := NewInmemTransport(addr)
	r2, err := NewRaft(conf, new(MockFSM), logs, stable, snaps, trans2)
	if err != nil {
		t.Fatalf("second NewRaft: %v", err)
	}
	f2 := r2.GetConfiguration()
	if err := f2.Error(); err != nil {
		t.Fatalf("GetConfiguration after restart: %v", err)
	}
	controlEvent(t, "control_restart", map[string]interface{}{
		"restore_committed": false,
		"servers_after":     len(f2.Configuration().Servers),
		"became_leader":     controlWaitLeader(r2, 3*time.Second),
		"snapshot_count":    len(snapList),
		"staged_commit":     staged,
	})
	_ = r2.Shutdown().Error()
}

package raft

import (
	"encoding/json"
